"c8vuhg": "La salle d'attente : les bots, le niveau de chacun, la manche et l'avance au départ.",
"5typne": "Vole l'école tout seul, sans bots.",
"1afdza": "Les bots, leur niveau de berger et quand la manche finit.",
"1t8ovw1": "Continue de rassembler ici seul, sans bots et sans chrono.",
"1087r08": "Les bots, leur niveau, la longueur des rubans et la manche.",
"1206cs3": "Continue de voler ici sans rubans et sans bots.",
"899bgs": "Les bots, leur niveau, la manche et la force des tirs.",
"172ev2t": "Continue de voler ici sans armes et sans bots.",
"1w5pf1h": "Boutons de canon et de missile",
"14d24dx": "Choisis un bouton ou un interrupteur pour chacun, et teste-les.",
"d2okc9": "Retour aux mini-jeux",
"j88ayy": "Reprendre",
"jsscfj": "Ça te semble bizarre ?",
"1emvcwj": "Jusqu'où vont les manches, et la limite des gaz. Les changer ici laisse le quad où il est et le chrono continue.",
"17lkkrv": "Ailleurs",
"1sc5qgc": "Ton nom, ta radio, les graphismes et le son.",
"6gxuho": "Termine {0}.",
"wyh1np": "Le poids ressenti du quad. À droite il est plus lourd : il tombe quand tu coupes les gaz et ne reste plus suspendu en haut d'un saut. À gauche il est plus léger, et il flotte. {0} est le quad tel qu'il est livré ; le changer en plein tour annule le tour, et un tour volé hors de {1} va sur le tableau public avec son poids à côté de ton nom.",
"1ayl725": "Accroche dans l'air",
"6bttpz": "À quel point l'air retient le quad, donc jusqu'où il glisse manches au centre. À gauche il continue sur sa lancée et va plus vite ; à droite l'air l'accroche, il s'arrête plus tôt et sa vitesse de pointe baisse. {0} est le quad tel qu'il est livré, réglé à partir des réglages envoyés par les pilotes. Le changer en plein tour annule le tour, et un tour volé hors de {1} est envoyé au tableau public avec l'étiquette Tuned.",
"ior56v": "Puissance moteur",
"1x4irmq": "La vitesse que les moteurs donnent par volt, leur KV. À gauche c'est plus doux : un punch plus sage et une vitesse de pointe plus basse. À droite c'est plus nerveux, la batterie s'affaisse davantage et le quad tient le stationnaire plus bas sur le manche. {0} est le quad tel qu'il est livré, réglé à partir des réglages envoyés par les pilotes. Le changer en plein tour annule le tour, et un tour volé hors de {1} est envoyé au tableau public avec l'étiquette Tuned.",
"1bsvonq": "Désactivé par défaut. Activé, {0} rejoignent Poids entre les manches quand le quad est au sol, et un vol avec tes propres curseurs se termine par une question : était-ce mieux que le quad d'origine ? Rien n'est envoyé sans ton oui. Désactivé, le quad vole tel qu'il est livré quoi que disent les curseurs. Le basculer en plein tour annule le tour si cela change le quad que tu voles.",
"5xvgod": "Demander après un vol réglé",
"1siorg1": "Quand un vol avec tes propres curseurs se termine, demande s'il était mieux que l'origine. Tu peux toujours répondre non, et rien n'est envoyé sans un oui. Désactivé, il ne demande jamais ; les curseurs marchent toujours.",
"187fv0s": "Dis au travail de réglage comment vole le quad. Un mot suffit ; ton réglage, ton ajustement PID et tes rates partent avec.",
"16us7mj": "Langue",
"2nnvct": "La langue des menus. Le jeu redémarre pour l'appliquer.",
"1hmyggy": "{0} a été essayé sur cette machine et n'a pas tenu l'image à temps, donc Auto reste à {1} ou en dessous.",
"s4dnb5": "Auto : dessine en {0}{1}. Il observe comment les images arrivent vraiment, baisse la résolution quand l'image est en retard et change de préréglage entre les runs.{2} Choisis un préréglage pour le fixer à la main.",
"1ejndm0": "Graphismes",
"dcm8ea": "Dessine chaque image directement à l'écran au lieu de la mettre en file derrière la page, ce qui peut retirer une image ou deux au délai entre tes manches et l'image. Peut provoquer du tearing.",
"1ttxrpl": "Désactivé au prochain chargement. {0} Ce navigateur l'utilise jusqu'au rechargement.",
"1j0ql37": "Désactivé. {0} Recharge après l'avoir activé.",
"o73nnv": "L'édition Steam peut tourner sans vsync.",
"101as9w": "l'écran se rafraîchit à {0} Hz",
"cfutp1": "le GPU met environ {0} ms de trop par image",
"gtjdfs": "L'affichage à faible latence est utilisé",
"1ampkwb": "Si cet écran peut dépasser 60 Hz, vérifie que le système est réglé sur sa fréquence maximale (Windows : Paramètres, Affichage, Affichage avancé), car la page ne peut dessiner qu'au rythme de l'écran qu'on lui donne.",
"13d5h9g": "De l'entrée à l'écran",
"9anx43": "Non mesurable ici",
"57y603": "Appuie sur quelques touches",
"ks1elk": "Environ {0} ms",
"12jryem": "Détection",
"h5se6q": "Lu depuis le contexte WebGL qui dessine le monde.",
"jgkrww": "Branche une radio en mode joystick. S'il y en a plusieurs, c'est ici que tu choisis laquelle vole.",
"1y6zyev": "Un appareil est branché, {0}. Ouvre ceci pour le confirmer ou pour passer au clavier.",
"1a5n4iv": "{0} appareils sont branchés. Bouge celui que tu veux. Windows les liste dans l'ordre des Contrôleurs de jeu ; c'est sur cet écran que tu choisis.",
"hkrgl0": "Un circuit à portes sur un terrain en plein air, contre le chrono. Un gros quad de course rapide, et chaque tour terminé peut aller sur le tableau public.",
"1rnl54t": "Le même chrono, en intérieur. Un minuscule whoop caréné sur un circuit qui tient dans un salon.",
"1kaa7l9": "Toutes les cartes freestyle : la ville, les maisons de Nick Burns, Heads et Joshua Bardwell, Thomas More's Shop, Sunnyfield, Shiokaze Point, Hibari Yard, et toutes les cartes que des pilotes ont construites et publiées sur le tableau. Pas de chrono, pas de portes, et les noms de figures s'activent à l'intérieur.",
"tn5ckg": "Éditeur",
"19ybx9k": "Crée le tien. Un circuit de course pour le cinq pouces, une pièce pour le whoop, ou une carte freestyle de bâtiments abandonnés, de grues et de gaps nommés, dessinée vue de dessus et volée depuis la même page.",
"1rjxeiy": "De ton premier stationnaire à une licence pro. Apprends à voler, gagne ta Licence Rookie, puis grimpe dans un arbre de compétences en course ou en freestyle. Commence ici si tu n'as jamais volé.",
"qci08u": "Arbre de compétences",
"my84jy": "Course ou freestyle",
"1k3pds0": "Batterie",
"1yly3ao": "au-dessus du sol",
"dp7pq5": "Gaz",
"enoiw8": "Lacet, gaz",
"umu7wd": "Poids, le poids ressenti du quad",
"1ory74v": "Temps d'image",
"t4w1kb": "Attends-toi à des bugs et à des finitions brutes. C'est encore en construction, et ça va s'améliorer.",
"67jzzb": "Bêta",
"3lorq6": "Revoler",
"1wio94n": "Commandes",
"152rjl0": "Un quad n'a ni freins ni ailes. Pointe-le où tu veux aller et pousse. Deux minutes et tu passeras une porte.",
"1l9ceev": "Simuler le FPV, pour les nerds",
"k33cv2": "Ouvrir le wiki FPV",
"1kmq093": "Comment voler",
"2qk4m1": "Ni freins ni ailes : pour ralentir ou tourner, pointe le quad ailleurs et pousse.",
"6del8m": "Radio ou manette",
"ap67uq": "Pourquoi ça marche : le wiki FPV",
"1uvpjn8": "Liste des figures",
"10sqi3d": "Chaque figure que le compteur sait nommer, ce qu'elle rapporte et à quoi elle ressemble. Choisis-en une et regarde : l'image est dessinée à partir de la même définition que celle utilisée par le compteur, donc ce que tu vois est exactement ce qu'il attend. Chacune a été volée et notée en test, c'est ce qui lui vaut sa place ici. Les points sont avant le combo, qui les multiplie.",
"onrqou": "À propos",
"15joiqz": "Qui a fait ça, sur le travail de qui ça repose, et comment les contacter.",
"15tzs71": "Circuits",
"wmughp": "Les tiens d'abord, puis le tableau",
"1lzo7zv": "Ordre des circuits du tableau",
"zw1xkn": "Terrain ouvert, pas de portes : la ville, ta carte ou une du tableau.",
"991pqy": "Du tableau, les plus récents d'abord",
"1sb6icu": "Quad",
"1g9ae39": "L'appareil, son réglage, la caméra et sa façon de voler.",
"4sc10z": "Acro. Les manches sont des vitesses de rotation. Mains lâchées, il tient.",
"56fkbd": "Toi, ta radio et tes rates, l'image et le son.",
