"r6kxsl": "Sortir les chèvres",
"131g0xg": "Toutes les chèvres de retour dans la rue et le chrono remis à zéro, pour les rassembler à nouveau. Une chèvre déjà vue reste vue.",
"8bhfu8": "Fantôme",
"1docbww": "Le tableau de ce circuit a déjà",
