"wv167q": "Toujours voler le {0} ici",
"10nopfd": "Champ de vision",
"unl4q1": "Plus large montre plus, plus étroit grossit. Étroit correspond à ce qu'un objectif FPV fait au centre de l'image ; Standard en rend un peu contre de la largeur ; Le plus large est aussi large que cette image peut honnêtement l'être, et les portes paraîtront plus petites.",
"4emmbg": "Fisheye",
"1u80da4": "Courbe l'image comme le fait un vrai objectif FPV : les coins restent là où le champ de vision les met, les bords se resserrent et le centre grossit. Désactivé donne une image droite, rectiligne. Si les vues larges te donnent la nausée, essaie Léger ou Moyen, et prends un champ de vision plus large pour retrouver la largeur.",
"1ir4yll": "Angle de caméra",
"6gsnw2": "À quel point la caméra est inclinée vers le haut par rapport au châssis. {0}, c'est à plat, dans l'axe du nez. {1}, c'est une croisière typique. De 45 à {2}, c'est la course. Au-delà d'environ 30, le lacet commence à faire rouler l'horizon : à {3} degrés, {4} pour cent d'un lacet apparaît comme du roulis à l'image. C'est ce que fait une vraie caméra inclinée. Baisse la vitesse max de lacet dans l'écran Rates pour calmer ça.",
"1vp9w8f": "Le lacet fera rouler l'horizon",
"1hjxoj1": "À {0} degrés d'inclinaison, {1} pour cent d'un lacet apparaît comme du roulis à l'image : {2} deg/s avec ta vitesse de lacet de {3} deg/s. C'est ce que fait une vraie caméra inclinée, et la réponse habituelle est un lacet plus lent. Baisser la vitesse max de lacet à {4} le ramène à {5} deg/s. Tu peux la changer à tout moment dans l'écran Rates.",
"1f9wwkb": "Garder ce rapport ?",
"v5eaek": "Tu as écrit quelque chose qui n'a pas été envoyé. Rien ici ne garde de brouillon, donc fermer maintenant le perd.",
"13qi8go": "Envoyer",
"ekjjsw": "Part de : les propres réglages Betaflight de l'auteur ({0} valeur modifiée{1})",
"hqa4hr": "PID : tels que le réglage est fourni",
"i1tfp3": "Poids {0}%, Accroche dans l'air {1}%, Puissance moteur {2}%",
"7x3x2g": "Batterie {0} V par cellule, objectif {1} degrés, inclinaison {2}°",
"nnhdr0": "Il est pour le {0}, donc tu passes à cet appareil et à sa propre classe de circuits.",
"1axqv1t": "Il modifie Accroche dans l'air ou Puissance moteur, donc le Réglage des sensations de vol est activé, et un tour volé avec est envoyé au tableau public avec l'étiquette Tuned.",
"t9yl6f": "Ses réglages Betaflight prennent la place de Tes modifications sur cet appareil jusqu'à ce que tu remettes les tiennes.",
"f50exw": "Tes graphismes, manches, radio et temps au tour ne sont pas touchés.",
"1e5r0vj": "Cette version ne peut pas voler ce réglage. Il est peut-être pour un appareil ajouté plus tard.",
"1os1q6k": "Ce réglage part d'un réglage Betaflight que cette version n'a pas.",
"13lnrfy": "Ce navigateur n'a pas pu garder le réglage. Le stockage est peut-être plein ou bloqué.",
"ut38q5": "Ça ne s'est pas ouvert. Vérifie la connexion, puis recharge la page.",
