"cf412e": "Marqué Poids {0}%.",
"1r80dho": "Une carte que tu as construite est différente pour chaque pilote, donc ses runs restent hors du tableau public.",
"ib1esm": "Le vol libre n'a pas de chrono, donc il n'a pas sa place sur le tableau. Passe Run sur Noté dans l'écran Freestyle.",
"6kanhw": "Un run sans figures n'est pas un score.",
"1x7qf08": "Ce run a utilisé les crochets de test, donc ce n'est pas un score volé.",
"e1s1lm": "Le poids a changé pendant ce run, donc il n'a pas un poids unique pour aller sur le tableau. Vole-le à nouveau avec un seul poids.",
"1gnhbo": "Les figures réussies avec Accroche dans l'air ou Puissance moteur ailleurs qu'à 100 restent hors du tableau public. Remets les deux à 100 et vole-le à nouveau.",
"10y1c4c": "Ce tableau est pour le quad pour lequel cette carte a été construite. Un run avec l'autre reste ici.",
"kr23p3": "Un run sur le tableau public a besoin d'un nom. Il reste dans ce navigateur.",
