"etis7d": "Ce circuit est déjà sur le tableau public.",
"k1lse7": "Le tracé a changé. Mettre à jour le tableau effacera les temps publiés.",
"1hwzdj3": "C'est ta copie{0}{1}. Elle va sur le tableau comme un nouveau circuit. L'original reste.",
"1188gek": "Le tableau public garde une copie de ce circuit, y compris chaque marque sur les portes, les drapeaux et l'herbe.",
"1ssz8g3": "Mettre à jour le tableau",
