"bjv4a4": "\"{0}\" publié. L'animation de sa carte n'a pas pu être envoyée.",
"9p6eg": "\"{0}\" publié, et sa carte sur le tableau est un tour de ce circuit.",
"1fjyb5y": "\"{0}\" publié. Son image de partage n'a pas pu être envoyée, donc un lien vers lui affiche la carte WebFPV pour l'instant.",
"11996s1": "Enregistré pour cette session seulement. Ce navigateur n'a pas voulu stocker le dump.",
