"ltlaqf": "L'aperçu 3D n'a pas pu démarrer.",
"nzydht": "Rates adoucis pour le vol aux pouces. 450 deg/s avec expo. À toi de les changer dans l'écran Rates.",
"1e62ufg": "Tu voles avec {0}. Choisis joystick dans les Paramètres pour en sélectionner un autre.",
