"zyxlra": "Interrupteur de redémarrage : {0}, jusqu'au rechargement. Ce navigateur n'a pas voulu le garder.",
"2bz9ml": "Interrupteur de reset auto : {0}. Un interrupteur l'active ou le désactive ; un bouton le bascule.",
"1qlbocd": "Interrupteur de reset auto : {0}, jusqu'au rechargement. Ce navigateur n'a pas voulu le garder.",
"svid14": "La carte graphique a cessé de dessiner. Recharge la page pour retrouver l'image.",
