"cyw1pe": "Un simulateur de course FPV dans le navigateur. Le contrôleur, c'est Betaflight. Le langage des circuits vient de Track Draw. Le reste, c'est un pilote et les gens qui l'ont volé jusqu'à ce que la sensation soit juste.",
"1sncokl": "Créé par",
"kai17": "A construit ce simulateur, l'éditeur et le tableau public. A orchestré une horde de Grok et de Claude en chemin.",
"1rju5ni": "Partenaires",
"10ax242": "Ils soutiennent WebFPV.",
"1fpu7yw": "Pilotes de bêta-test",
"2sef6d": "Ils l'ont volé jusqu'à ce qu'il se comporte comme un quad.",
"lq4qk4": "Le contrôleur",
"152d3mr": "Les rates, la boucle PID, les filtres, le feedforward, le TPA, l'iterm relax, l'airmode, l'anti-gravity. Compilés dans cette page, pas réécrits.",
"kfh8vm": "est sous GPLv3, donc ceci aussi. L'écran du contrôleur de vol est un hommage à",
"1ol0nlq": "10.10 : les noms d'onglets, les champs de la 4.5.1, et le gris foncé et orange classique. Ce n'est pas cette application. Pas de Vue, pas de MSP, pas d'iframe. Avec nos remerciements aux développeurs de Betaflight.",
"kwollz": "Le langage des circuits",
"91xq6y": "L'éditeur est inspiré de",
"1v1kv66": ", des dieux néerlandais du drone de",
"1ffizjn": "Les salles RaceGOW5",
"ov7ihs": "Huit circuits, six constructeurs, relevés sur les animations officielles.",
"f0ewtp": "Série et animations par",
"432t9y": "La horde",
"gw6sa5": "Écrit avec Grok. Construit avec Claude.",
"1m26mn1": "Grok, de xAI. Beaucoup de lignes, beaucoup de débats, et beaucoup d'entêtement sur la sensation de vol.",
"1i8y2kj": "Claude, d'Anthropic. L'autre moitié de la horde. Le même humain aux manches.",
"sskqzq": "Betaflight, Track Draw, Grok, Claude, Dutch Drone Squad et leurs marques appartiennent à leurs propriétaires. Les images des chaînes appartiennent aux pilotes. Les utiliser ici est un crédit, pas une affirmation qu'ils cautionnent cette page. Les marques des partenaires appartiennent aux partenaires et sont affichées avec leur accord. WebFPV est un logiciel libre sous",
