"28mh9p": "La manche se termine quand toutes les chèvres sont rentrées. Celui qui a le plus de chèvres gagne.",
"1t6qjon": "Personne d'autre ne vole pour l'instant, donc c'est un vol d'entraînement avec ton ruban.",
