"p8yx1": "Coups durs : il faut moins de coups pour t'éclater et tu attends plus longtemps avant de revenir.",
"1dsfhgk": "Éclaté ne veut pas dire éliminé : tu reviens en trois secondes.",
"1l302t4": "Prépare :",
"1ra2hmr": "Touche un quad pour lui retirer de la vie. Quand elle est vide, il éclate, avec des confettis. Chaque quad éclaté vaut un point. Un missile suit un quad dès que le cadre devient rouge.",
"abeo2g": "Au combat !",
"43eacj": "Chaque quad traîne un ruban. Traverse celui d'un autre pour le couper. Garde le tien loin d'eux. Coupé jusqu'au bout, le ruban disparaît et son pilote aussi. Le dernier ruban gagne.",
"1tj1cwp": "Volez !",
"11xt3fz": "Vole bas derrière une chèvre et elle te fuit. Pousse-la dans le garage de Heads. Chaque chèvre appartient à celui qui l'a rentrée en dernier, alors vole-les à la porte.",
"1xzga63": "Rassemblez !",
"ckuwmm": "Choisis ton camp et les bots prennent toutes les autres places. Ça démarre en quelques secondes, sans attendre personne.",
