"1bvgnvq": "Crée une partie privée et envoie son code, ou tape le code d'un ami. Les bots gardent les places vides, et un ami qui rejoint en prend une.",
"lblpf4": "De vrais pilotes",
"1joy1ch": "Donne le coup d'envoi maintenant avec des bots. Un autre pilote qui choisit Partie rapide prend la place d'un bot. Chat prédéfini uniquement.",
