"60bmqc": "Quad Ball, partie privée",
"fgk4f3": "Quad Ball, partie rapide",
"65gil7": "Fonce dans le ballon pour le frapper. Plus tu fonces fort, plus il part fort. Les roses défendent le but ouest et attaquent le but est ; les menthe font l'inverse. Après un but, tout le monde a quelques secondes pour revenir pour l'engagement.",
"j3lmwm": "Créer la partie",
"1clgctl": "Coup d'envoi !",
"mja9lm": "Poursuis les pilotes pendant une minute. Près, fluide, la moto au centre de l'image, un whip ou un grand saut, et les zones de clipping : tout rapporte des points. La meilleure bobine gagne.",
"1srrqzv": "Filme les battles de drift pendant une minute. Près, fluide, la voiture au centre de l'image, les deux voitures d'un battle, et les zones de clipping : tout rapporte des points. La meilleure bobine gagne.",
