"dfet3": "Ouverture",
"zd85cj": "Supprimer \"{0}\" de ce navigateur. Annuler le remet tant que cette liste est ouverte.",
"9jdqur": "Cartes enregistrées",
"opql46": "Des circuits cinq pouces que d'autres pilotes ont mis sur Cartes et Circuits. Ouvres-en un et c'est ta copie : change ce que tu veux, et publie-le sous un nom à toi. L'original reste le leur.",
"1d1l6my": "Demande de ses circuits au tableau.",
"1ax09zh": "Partir d'un circuit du tableau",
"8ybw7e": "Porte, dans Outils, en commence un de zéro.",
"t4qycv": "Porte, à gauche, en commence un de zéro.",
"l4g0hw": "Le tableau n'a pas pu être joint, donc ses circuits ne peuvent pas être listés.",
