"10na0yf": "Les officiels peuvent être volés, et seul un admin du tableau peut les ouvrir ici.",
"1ixisp3": "Ouvrir une copie",
"hnr5lv": "Ta propre copie de \"{0}\", à modifier et à publier sous ton nom",
"q7urfa": "\"{0}\" est un circuit officiel. Tout le monde peut y voler, et seul un admin du tableau peut l'ouvrir dans l'éditeur.",
"nagfjo": "\"{0}\" n'a pas pu être récupéré sur le tableau.",
"v7bdaq": "C'est ta copie de \"{0}\"{1}. Publie-la sous un nouveau nom pour la mettre sur le tableau.",
"1anoug0": "Impossible de supprimer \"{0}\" : le stockage local est indisponible.",
