"122ipps": "Impossible de créer un lien pour ce circuit.",
"10mrwp2": "Il est long parce qu'il transporte les logos des sponsors, et certaines applis de discussion coupent un lien aussi long : pour celles-là, exporte le fichier depuis Plus.",
"kzs3eg": "Lien de partage",
"g3w5en": "L'image montre la pièce en 3D. Appuie d'abord sur V, ou sur 3D dans la barre.",
"1g5qw8a": "La pièce n'est pas encore affichée, donc il n'y a rien à photographier.",
