"1wk3175": "Rien à rétablir.",
"w9y7dg": "Chacun garde son propre travail, donc on ne perd rien en choisissant. Le sélecteur {0} en haut à gauche passe de l'un à l'autre à tout moment.",
"1glss62": "Quel canevas",
