"w7fg15": "Rétablir",
"ujhnmy": "Vue d'édition du dessus",
"7wf4nz": "Construire ici, en 3D",
"qbnrkk": "Regarde la pièce à la verticale, nord en haut, pour mesurer. Appuie de nouveau pour retrouver l'angle que tu avais. Tous les gestes restent les mêmes.",
"r8dtlq": "Dessiner la trajectoire de course sur le canevas",
"14i9zd2": "Numéros de l'ordre de vol sur les portes. Désactive-les pour voir la trajectoire de course.",
"1vg48it": "Les nouvelles portes s'orientent selon l'axe le plus proche et y restent, comme on dessine un plan. Désactivé, elles s'orientent le long de la ligne venant de la précédente.",
"1ielrzy": "Fais glisser la trajectoire de course pour la courber en un point de passage. Désactivé, un clic sur une porte est un clic sur la porte.",
"1v9gbxt": "Construis le monde autour de ce circuit et vole dessus",
