"duvt42": "Le plan vu du dessus, le canevas que cet éditeur a toujours eu. V pour la 3D",
"6hw2u8": "Construire ici, en 3D : choisis une pièce à gauche, clique sur {0}, fais glisser une pièce pour la déplacer. V pour la 2D",
"80c142": "Cadrer le circuit",
"xubvlq": "Les étiquettes des gaps nommés et les noms sur le plan. Désactive-les pour voir la carte.",
"lppay7": "Construis cette carte dans le style de la ville et vole dessus en cinq pouces",
