"1ti6h5c": "Couvert",
"1kq6380": "Heure dorée : un soleil bas et chaud et de longues ombres violettes. La lumière propre à la ville.",
"r0wxsi": "Un soleil haut et blanc, des ombres courtes et dures et un ciel bleu profond.",
"ige15v": "Le soleil sur l'horizon et un ciel violet. Les fenêtres, les lampadaires, les panneaux et les distributeurs s'allument.",
