"wnpobs": "Une cour de dalles de béton sciées, avec une ligne jaune autour.",
"yi1f2h": "Un parking sombre, avec des places et des flèches peintes autour de tout ce que tu poses.",
"1a197nq": "Une pelouse à l'intérieur de la bordure. Aucune ligne n'y est peinte sauf la zone de départ.",
